import{_ as a,o as r,c as e,a5 as d}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"家庭学习共同协议：十四天，把帮助变得可商量","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/family-learning-agreement.zh.md","filePath":"public/downloads/worksheets/family-learning-agreement.zh.md","lastUpdated":1795488252000}'),l={name:"public/downloads/worksheets/family-learning-agreement.zh.md"};function h(i,t,o,b,n,p){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="家庭学习共同协议-十四天-把帮助变得可商量" tabindex="-1">家庭学习共同协议：十四天，把帮助变得可商量 <a class="header-anchor" href="#家庭学习共同协议-十四天-把帮助变得可商量" aria-label="Permalink to &quot;家庭学习共同协议：十四天，把帮助变得可商量&quot;">​</a></h1><p>这不是家长给孩子下达的合同，也不是要求孩子签字服从的承诺。它是一张私密工作纸，让学习者、家长或监护人把同一件事各自写清楚，再用十四天事实决定下一步。</p><p>请保存在家庭私有位置。不要写入密码、证件号码、精确地址、学校内部账号、医疗记录、同学或教师的私人信息。不要把协议、基线或失败样本公开展示，除非学习者理解公开范围、相关人员已经授权，并且内容已经最小化处理。</p><h2 id="_1-分别写-再一起读" tabindex="-1">1. 分别写，再一起读 <a class="header-anchor" href="#_1-分别写-再一起读" aria-label="Permalink to &quot;1. 分别写，再一起读&quot;">​</a></h2><h3 id="学习者先写" tabindex="-1">学习者先写 <a class="header-anchor" href="#学习者先写" aria-label="Permalink to &quot;学习者先写&quot;">​</a></h3><p>我希望两周后哪件真实事情变容易一点：<br> 我现在已经能够完成什么：<br> 我最常停住的地方：<br> 哪一种帮助对我有用：<br> 哪一种帮助让我更难开始或不愿说实话：<br> 今天我能承担的时间与容量：</p><h3 id="家长-监护人再写" tabindex="-1">家长/监护人再写 <a class="header-anchor" href="#家长-监护人再写" aria-label="Permalink to &quot;家长/监护人再写&quot;">​</a></h3><p>我观察到的具体事实：<br> 我最担心的事情：<br> 哪些担心有证据：<br> 哪些部分仍然只是我的推测：<br> 我能提供的时间、空间、设备或沟通支持：<br> 我承诺不做的监督、代做或公开行为：</p><p>一起阅读时，不立即反驳。先用一句话复述对方的意思，直到对方认为基本准确。</p><h2 id="_2-写成一个共同问题" tabindex="-1">2. 写成一个共同问题 <a class="header-anchor" href="#_2-写成一个共同问题" aria-label="Permalink to &quot;2. 写成一个共同问题&quot;">​</a></h2><p>十四天只回答的问题：<br> 它发生在哪个学校或生活场景：<br> 学校明确要求：<br> 孩子自己的完成标准：<br> 成人必须保护的安全与责任边界：<br> 什么结果会让我们继续：<br> 什么结果会让我们缩小、暂停或停止：</p><p>共同问题应允许不成功。例如：“能否在两周后独立复述相近文章的主旨”比“词汇量必须增加 500”更容易保留真实结果。</p><h2 id="_3-保存起点" tabindex="-1">3. 保存起点 <a class="header-anchor" href="#_3-保存起点" aria-label="Permalink to &quot;3. 保存起点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>任务与限制</th><th>学习者独立结果</th><th>提示出现在哪里</th><th>原始证据位置</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>起点能够说明：<br> 起点仍然不能说明：<br> 这次只改变的一个条件：</p><p>成人可以帮助保存文件，不在基线完成前给出完整答案。</p><h2 id="_4-三个容量档位" tabindex="-1">4. 三个容量档位 <a class="header-anchor" href="#_4-三个容量档位" aria-label="Permalink to &quot;4. 三个容量档位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>档位</th><th>适用情况</th><th>学习者保留的动作</th><th>成人保留的支持</th></tr></thead><tbody><tr><td>完整日</td><td></td><td></td><td></td></tr><tr><td>压缩日</td><td></td><td></td><td></td></tr><tr><td>恢复日</td><td></td><td></td><td></td></tr></tbody></table><p>最晚结束时间：<br> 明确不补做的内容：<br> 中断后 24 小时内的最小回归动作：</p><p>恢复日可以没有学习作品。安全、基本照料、沟通和准备下次入口可以是当天全部结果。</p><h2 id="_5-成人支持清单" tabindex="-1">5. 成人支持清单 <a class="header-anchor" href="#_5-成人支持清单" aria-label="Permalink to &quot;5. 成人支持清单&quot;">​</a></h2><p>这两周，成人只选择两到三项：</p><ul><li>[ ] 提供一个不被随意打断的时间盒；</li><li>[ ] 准备学校指定材料或必要设备；</li><li>[ ] 帮助联系教师或确认作业要求；</li><li>[ ] 在孩子提交首版后，提供最多三条具体反馈；</li><li>[ ] 在约定时间提醒一次，不重复追问；</li><li>[ ] 帮助保存版本和下一步入口；</li><li>[ ] 当容量下降时主动同意降档或暂停。</li></ul><p>成人明确不做：</p><ul><li>[ ] 不代写、代答或让 AI 代做后要求孩子署名；</li><li>[ ] 不全天查看屏幕、聊天记录或每分钟状态；</li><li>[ ] 不把作品、成绩或失败发给无关亲友或公开平台；</li><li>[ ] 不用同学、兄弟姐妹或过去的高光时刻羞辱比较；</li><li>[ ] 不用熬夜、取消基本休息或持续冲突偿还计划。</li></ul><h2 id="_6-ai-与数据约定" tabindex="-1">6. AI 与数据约定 <a class="header-anchor" href="#_6-ai-与数据约定" aria-label="Permalink to &quot;6. AI 与数据约定&quot;">​</a></h2><p>允许使用的平台与账户：<br> 平台当前年龄/监护规则已核对：是 / 否 / 不适用<br> 学校是否允许本任务使用 AI：<br> AI 可以做：提问 / 解释 / 反馈 / 平行练习 / 其他<br> AI 不可以做：<br> 孩子必须先提交的独立版本：<br> 每次使用后要保存的证据：<br> 会话结束后的复述或独立动作：</p><p>绝不上传：</p><ul><li>[ ] 姓名、学校、班级、证件、精确地址和私人联系方式；</li><li>[ ] 面部、声纹、健康、家庭关系和未经最小化的成绩记录；</li><li>[ ] 教师、同学和其他第三方的私人信息或未授权作品；</li><li>[ ] 学校内部账号、试卷答案、受限制材料或家庭敏感信息。</li></ul><p>若平台、学校或家庭无法确认边界，就先使用纸笔、离线材料、合成数据或教师批准的替代方式。</p><h2 id="_7-反馈规则" tabindex="-1">7. 反馈规则 <a class="header-anchor" href="#_7-反馈规则" aria-label="Permalink to &quot;7. 反馈规则&quot;">​</a></h2><p>每次只保留的一个主问题：<br> 成人最多提供几条反馈：<br> 学习者可以如何拒绝或追问反馈：<br> 发生分歧时先确认哪项事实：<br> 何时需要请教师参与：</p><p>反馈句式：</p><p>我观察到：<br> 它对任务的影响：<br> 我不确定的是：<br> 我建议下一次只测试：</p><p>避免“你就是……”“你从来不……”和“别人都能……”。</p><h2 id="_8-十四天证据" tabindex="-1">8. 十四天证据 <a class="header-anchor" href="#_8-十四天证据" aria-label="Permalink to &quot;8. 十四天证据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间点</th><th>条件</th><th>独立结果</th><th>得到的反馈</th><th>仍然未知</th></tr></thead><tbody><tr><td>第 1 天基线</td><td></td><td></td><td></td><td></td></tr><tr><td>即时修订</td><td></td><td></td><td></td><td></td></tr><tr><td>延迟复测</td><td></td><td></td><td></td><td></td></tr><tr><td>新条件迁移</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>聊天时长、打卡天数和家长提醒次数只是过程痕迹。关键判断应回到作品、题目、录音、课堂使用和撤掉提示后的表现。</p><h2 id="_9-暂停与求助门" tabindex="-1">9. 暂停与求助门 <a class="header-anchor" href="#_9-暂停与求助门" aria-label="Permalink to &quot;9. 暂停与求助门&quot;">​</a></h2><p>出现哪些安全、身体、睡眠、情绪、校园或家庭情况时立即暂停：<br> 孩子可以先联系的可信成人：<br> 学校联系入口：<br> 当地专业或紧急支持入口：<br> 暂停后不需要补做的内容：</p><p>出现持续功能受损、伤害念头、暴力、欺凌、威胁或无法安全沟通时，先保护安全并寻求合适支持，不用这张表自行诊断或处理。</p><h2 id="_10-两周复盘-学习者先说" tabindex="-1">10. 两周复盘：学习者先说 <a class="header-anchor" href="#_10-两周复盘-学习者先说" aria-label="Permalink to &quot;10. 两周复盘：学习者先说&quot;">​</a></h2><h3 id="学习者" tabindex="-1">学习者 <a class="header-anchor" href="#学习者" aria-label="Permalink to &quot;学习者&quot;">​</a></h3><p>真正变容易的一件事：<br> 仍然不会或需要提示的一件事：<br> 最有用的支持：<br> 最没有价值或让我不舒服的监督：<br> 下一步我愿意继续的动作：</p><h3 id="家长-监护人" tabindex="-1">家长/监护人 <a class="header-anchor" href="#家长-监护人" aria-label="Permalink to &quot;家长/监护人&quot;">​</a></h3><p>我观察到的作品与事实：<br> 我减少了什么控制或无效要求：<br> 我仍然担心但尚无足够证据的部分：<br> 下一轮我只保留的支持：</p><h3 id="共同决定" tabindex="-1">共同决定 <a class="header-anchor" href="#共同决定" aria-label="Permalink to &quot;共同决定&quot;">​</a></h3><p>继续 / 缩小 / 改变一个条件 / 暂停或停止：<br> 依据：<br> 下一项最小任务：<br> 下一次复查日期：<br> 需要教师或专业人员参与的事项：</p><h2 id="结尾-帮助也要接受复盘" tabindex="-1">结尾：帮助也要接受复盘 <a class="header-anchor" href="#结尾-帮助也要接受复盘" aria-label="Permalink to &quot;结尾：帮助也要接受复盘&quot;">​</a></h2><p>家庭通常会复盘孩子是否完成，很少复盘成人的帮助是否有效。这张协议要求双方都留下证据：孩子的任务是否更清楚，成人的支持是否降低了摩擦，关系是否仍然能够说真话。</p><p>当帮助只剩监控、代做和焦虑传递时，它也需要被缩小或停止。好的支持不一定让孩子立刻做得更多，却会让他逐渐更能看见问题、提出需要、承担自己的版本，并知道困难出现时可以向谁求助。</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-4/family-learning" target="_blank" rel="noreferrer">家庭学习篇：把成长还给孩子</a> ｜ <a href="https://byoungd.github.io/up/threads/part-4/week-1" target="_blank" rel="noreferrer">实践篇</a> ｜ <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/family-learning-agreement" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',54)])])}const c=a(l,[["render",h]]);export{u as __pageData,c as default};
